-- Extend the existing identity/content foundation. No production users or default credentials are created.
alter table public.roles drop constraint if exists roles_name_check;
alter table public.roles add constraint roles_name_check check(name in ('OWNER','SUPER_ADMIN','ADMIN','EDITOR_IN_CHIEF','EDITOR','AUTHOR','MODERATOR','VIEWER'));
insert into public.roles(name) values('SUPER_ADMIN'),('EDITOR_IN_CHIEF'),('MODERATOR'),('VIEWER') on conflict(name) do nothing;
alter table public.user_roles add column if not exists is_active boolean not null default true;
alter table public.user_roles add column if not exists granted_by uuid references auth.users(id) on delete set null;
alter table public.user_roles add column if not exists granted_at timestamptz not null default now();
create table if not exists public.permissions(key text primary key,description text not null default '');
alter table public.permissions enable row level security;revoke all on public.permissions from public,anon,authenticated;
create table if not exists public.role_permissions(role_id uuid references public.roles(id) on delete cascade,permission_key text references public.permissions(key) on delete cascade,scope text not null default 'all' check(scope in ('own','all')),enabled boolean not null default true,primary key(role_id,permission_key));
alter table public.role_permissions enable row level security;revoke all on public.role_permissions from public,anon,authenticated;
create table if not exists public.user_permissions(user_id uuid references auth.users(id) on delete cascade,permission_key text references public.permissions(key) on delete cascade,effect text not null check(effect in ('allow','deny')),scope text not null default 'all' check(scope in ('own','all')),enabled boolean not null default true,assigned_by uuid references auth.users(id) on delete set null,primary key(user_id,permission_key));
alter table public.user_permissions enable row level security;revoke all on public.user_permissions from public,anon,authenticated;
create table if not exists public.admin_memberships(user_id uuid primary key references auth.users(id) on delete cascade,enabled boolean not null default true,scope_mode text not null default 'all' check(scope_mode in ('all','restricted')),category_ids uuid[] not null default '{}',assigned_by uuid references auth.users(id) on delete set null,assigned_at timestamptz not null default now(),last_activity_at timestamptz,revoked_before timestamptz not null default '1970-01-01');
alter table public.admin_memberships enable row level security;revoke all on public.admin_memberships from public,anon,authenticated;
create table if not exists public.admin_invitations(id uuid primary key default gen_random_uuid(),email text not null,role_id uuid not null references public.roles(id) on delete restrict,token_hash text not null unique check(token_hash ~ '^[a-f0-9]{64}$'),status text not null default 'pending' check(status in ('pending','accepted','revoked')),scope_mode text not null default 'all' check(scope_mode in ('all','restricted')),category_ids uuid[] not null default '{}',created_by uuid references auth.users(id) on delete set null,accepted_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),expires_at timestamptz not null,accepted_at timestamptz,delivery_status text not null default 'pending' check(delivery_status in ('pending','sent','failed')));
alter table public.admin_invitations enable row level security;revoke all on public.admin_invitations from public,anon,authenticated;
create table if not exists public.security_events(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id) on delete set null,event_type text not null,result text not null check(result in ('success','failure')),request_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());
alter table public.security_events enable row level security;revoke all on public.security_events from public,anon,authenticated;
create table if not exists public.admin_notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,kind text not null,title text not null,href text not null check(href like '/admin/%' and href not like '//%'),priority text not null default 'normal' check(priority in ('normal','high')),read_at timestamptz,archived_at timestamptz,created_at timestamptz not null default now());
alter table public.admin_notifications enable row level security;revoke all on public.admin_notifications from public,anon,authenticated;
create table if not exists public.menu_items(id uuid primary key default gen_random_uuid(),parent_id uuid references public.menu_items(id) on delete restrict,location text not null check(location in ('header','mobile','footer','secondary')),label text not null check(length(label) between 1 and 100),target_type text not null check(target_type in ('page','category','external')),href text,category_id uuid references public.categories(id) on delete restrict,is_active boolean not null default true,sort_order int not null default 0,deleted_at timestamptz,created_at timestamptz not null default now(),check((target_type='category' and category_id is not null) or (target_type in ('page','external') and href is not null)));
alter table public.menu_items enable row level security;revoke all on public.menu_items from public,anon,authenticated;
create table if not exists public.integration_settings(id text primary key check(id in ('supabase','vercel','telegram','botkeep','ai','analytics')),enabled boolean not null default false,config jsonb not null default '{}',updated_at timestamptz not null default now());
alter table public.integration_settings enable row level security;revoke all on public.integration_settings from public,anon,authenticated;
create table if not exists private.pin_controls(user_id uuid primary key references auth.users(id) on delete cascade,epoch int not null default 1,require_sensitive boolean not null default true,ttl_seconds int not null default 600 check(ttl_seconds between 60 and 900),failures int not null default 0,locked_until timestamptz);
alter table private.pin_controls enable row level security;revoke all on private.pin_controls from public,anon,authenticated;
create table if not exists private.sensitive_proofs(proof_hash text primary key check(proof_hash ~ '^[a-f0-9]{64}$'),user_id uuid not null references auth.users(id) on delete cascade,session_id uuid not null,epoch int not null,expires_at timestamptz not null,strong_until timestamptz);
alter table private.sensitive_proofs enable row level security;revoke all on private.sensitive_proofs from public,anon,authenticated;
alter table public.audit_logs add column if not exists metadata jsonb not null default '{}';
alter table public.audit_logs add column if not exists request_id uuid not null default gen_random_uuid();
alter table public.audit_logs add column if not exists result text not null default 'success' check(result in ('success','failure'));
create index if not exists user_roles_granter_idx on public.user_roles(granted_by);
create index if not exists permission_role_key_idx on public.role_permissions(permission_key,role_id);
create index if not exists permission_user_key_idx on public.user_permissions(permission_key,user_id);
create index if not exists user_permissions_assigner_idx on public.user_permissions(assigned_by);
create index if not exists membership_assigner_idx on public.admin_memberships(assigned_by);
create index if not exists invitations_email_idx on public.admin_invitations(email,status,expires_at);
create index if not exists invitations_role_idx on public.admin_invitations(role_id);
create index if not exists invitations_creator_idx on public.admin_invitations(created_by);
create index if not exists invitations_acceptor_idx on public.admin_invitations(accepted_by);
create index if not exists security_actor_time_idx on public.security_events(actor_id,created_at desc);
create index if not exists notifications_user_time_idx on public.admin_notifications(user_id,created_at desc);
create index if not exists menu_parent_idx on public.menu_items(parent_id);
create index if not exists menu_category_idx on public.menu_items(category_id);
create index if not exists proofs_user_idx on private.sensitive_proofs(user_id,session_id,expires_at);
create index if not exists audit_time_idx on public.audit_logs(created_at desc,id);
insert into public.permissions(key) values ('posts.create'),('posts.read'),('posts.update'),('posts.publish'),('posts.delete'),('posts.schedule'),('categories.manage'),('authors.manage'),('media.manage'),('comments.moderate'),('users.invite'),('users.manage'),('roles.manage'),('settings.read'),('settings.update'),('security.manage'),('integrations.manage'),('analytics.read'),('audit.read'),('dashboard.read'),('notifications.read'),('menus.manage'),('announcements.manage'),('maintenance.manage'),('backups.read') on conflict(key) do nothing;
insert into public.role_permissions(role_id,permission_key,scope) select id,'posts.create','all' from public.roles where name='SUPER_ADMIN' on conflict do nothing;
insert into public.role_permissions(role_id,permission_key,scope) select id,'posts.read','all' from public.roles where name='SUPER_ADMIN' on conflict do nothing;
insert into public.role_permissions(role_id,permission_key,scope) select id,'posts.update','all' from public.roles where name='SUPER_ADMIN' on conflict do nothing;
insert into public.role_permissions(role_id,permission_key,scope) select id,'posts.publish','all' from public.roles where name='SUPER_ADMIN' on conflict do nothing;
insert into public.role_permissions(role_id,permission_key,scope) select id,'posts.delete','all' from public.roles where name='SUPER_ADMIN' on conflict do nothing;
